{"file_path":"/work/tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_includes_none_in_denominator():
    assert conversion_rate([{"converted": None}, {"converted": True}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (2, 5), (10, 6)])
def test_conversion_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_log_fields_and_skipped_lines():
    lines = ["a , 1 , 1", "", " b , 2 , 0 ", "  # ignored", " \t", "c,3, "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,two,0"])
def test_log_errors_count_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["", "ok,1,0", " # comment", bad_line])


def test_dedupe_keeps_last_record_then_sorts_by_day_and_id():
    events = parse_session_log(["a,1,1", "c,3,0", "b,2,1", "a,3,0"])
    assert dedupe_sessions(events) == [events[2], events[3], events[1]]


def test_daily_counts_cover_only_requested_range():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1"])
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_session_log(["a,1,1", "b,4,1"]), "b": parse_session_log(["c,6,0"]), "c": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rankings_and_rates():
    groups = {"b": [{"converted": False}], "c": [{"converted": True}], "a": [{"converted": None}], "d": []}
    assert top_converting_groups(groups, 5) == ["c", "a", "b"]
    assert top_converting_groups(groups, 2) == ["c", "a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 0.0), ("b", 0.0), ("c", 1.0), ("d", None)]


@pytest.mark.parametrize("counts,expected", [([], 0), ([0, -1], 0), ([1, 0, 2, 3, -1, 1], 2)])
def test_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_conversion_streak(counts) == expected
